# -*- coding: utf-8 -*-
# Escribe los archivos completos: no preguntar en YouTube Music ni previews.
from pathlib import Path
import sys, base64

ROOT = Path(__file__).resolve().parent
if not (ROOT / "app" / "profile" / "page.js").exists():
    print("ERROR: corre esto DENTRO de musica-libre")
    print("Estas en:", ROOT)
    sys.exit(1)

D0 = """\

"""
D1 = """\

"""
D2 = """\

"""
D3 = """\

"""
D4 = """\

"""

p = ROOT / 'app/profile/page.js'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(D0))
print("ESCRITO", 'app/profile/page.js', p.stat().st_size, "bytes")

p = ROOT / 'app/spotify/page.js'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(D1))
print("ESCRITO", 'app/spotify/page.js', p.stat().st_size, "bytes")

p = ROOT / 'app/components/DownloadManager.js'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(D2))
print("ESCRITO", 'app/components/DownloadManager.js', p.stat().st_size, "bytes")

p = ROOT / 'public/sw.js'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(D3))
print("ESCRITO", 'public/sw.js', p.stat().st_size, "bytes")

p = ROOT / 'public/novedades.json'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(D4))
print("ESCRITO", 'public/novedades.json', p.stat().st_size, "bytes")

txt = (ROOT / "app/profile/page.js").read_text(encoding="utf-8")
ok = (
    "function esYoutubeMusic" in txt
    and "if (esYoutubeMusic(item)) return false" in txt
    and "!esYoutubeMusic(item) && !estaVerificadaLocal" in txt
)
sp = (ROOT / "app/spotify/page.js").read_text(encoding="utf-8")
ok = ok and 'source: "ytmusic", ytmusic: true' in sp
dm = (ROOT / "app/components/DownloadManager.js").read_text(encoding="utf-8")
ok = ok and "ytmusic: Boolean(t.ytmusic" in dm
print("LISTO" if ok else "FALLO")
if not ok:
    sys.exit(1)
print("GitHub Desktop: Commit to main")
print("mensaje: No preguntar en YouTube Music")
print("despues: Push origin")
